		const hasDupPassedNdt = Boolean(j.dupNdtType) && j.dupNdtType !== "Не требуется" && j.dupNdtResult === "Годен";
		const hasRepairPassedNdt = j.repairNdtResult === "Годен" && j.repairNdtType !== "Не требуется" || j.repairDupNdtResult === "Годен" && j.repairDupNdtType !== "Не требуется";
		const hasOpenNdtDefect = j.ndtResult === "Ремонт" || j.ndtResult === "Вырезать" || j.dupNdtResult === "Ремонт" || j.dupNdtResult === "Вырезать";
		const hasAnyNdt = hasRepairPassedNdt || !hasOpenNdtDefect && (hasPrimaryPassedNdt || hasDupPassedNdt);
