/**
* Определяет НД на сварочный материал
*/
function inferWeldingConsumableNtd(brandPart) {
	const s = brandPart.toLowerCase();
	if (s.includes("св-04х") || s.includes("св-08г2с") || s.startsWith("св-")) return "ГОСТ 2246-70";
	if (s.includes("уони") || s.includes("lb-52") || s.includes("ок ") || s.includes("ok ") || s.includes("цл-") || s.includes("озл-")) return "ГОСТ 9466-75";
	if (s.includes("co2") && s.includes("ar")) return "ТУ 2114-004-00204760-99";
	if (s.includes("ar")) return "ГОСТ 10157-2016";
	if (s.includes("co2")) return "ГОСТ 8050-85";
	return "ГОСТ 2246-70";
}
/**
* Форматирует сварочные материалы для графы 8 журнала по ГОСТ 32569-2013
*/
function formatGost32569ConsumablesCell(rawMaterials, materialsCatalog = []) {
	const raw = (rawMaterials || "").trim();
	if (!raw) return "н/п";
	const matchedMat = materialsCatalog.find((m) => m.brandAndDiameter === raw || m.brandAndDiameter.toLowerCase() === raw.toLowerCase());
	const parts = [];
	let working = raw;
	const parenMatches = working.match(/\(([^)]+)\)/g);
	const trailingParens = [];
	if (parenMatches) for (const pm of parenMatches) {
		const inner = pm.slice(1, -1).trim();
		if (inner) trailingParens.push(inner);
		working = working.replace(pm, "").trim();
	}
	const splitMain = working.split(/\s+\/\s+|;\s*|\n+/).map((p) => p.replace(/[()]/g, "").trim()).filter(Boolean);
	parts.push(...splitMain, ...trailingParens);
	if (parts.length === 0) return "н/п";
	const rawCertParts = matchedMat ? matchedMat.certificateNumber.replace(/серт\.?\s*№?\s*/gi, "").split(/\s+\/\s+|,\s*/).map((c) => c.replace(/[()]/g, "").trim()).filter(Boolean) : [];
	const rawBatchParts = matchedMat ? matchedMat.batchNumber.split(/\s+\/\s+|,\s*/).map((b) => b.replace(/пл\.?\s*/gi, "").replace(/партия\s*/gi, "").replace(/баллон\s*ar\s*№?\s*/gi, "АР-").replace(/смесь\s*/gi, "").replace(/[()]/g, "").trim()).filter(Boolean) : [];
	return parts.map((part, idx) => {
		return [
			part,
			inferWeldingConsumableNtd(part),
			rawCertParts[idx] || rawBatchParts[idx] || rawCertParts[0] || ""
		].filter(Boolean).join(", ");
	}).join("\n");
}
/**
* Нормализует значение ячейки журнала ГОСТ
*/
function normalizeGostNotApplicable(val) {
	const trimmed = (val || "").trim();
	if (!trimmed) return "";
	const lower = trimmed.toLowerCase();
	if (lower === "не требуется" || lower === "не проводился" || lower === "н/п" || lower === "нет") return "н/п";
	return trimmed;
}
/**
* Формирует все 17 граф строки журнала сварки по ГОСТ 32569-2013 для заданного стыка.
*/
/**
* Проверяет, подвергался ли сварной стык ремонту (устранение дефекта, ремонтный шов, повторный контроль).
*/
function isJointRepaired(joint) {
	return Boolean(joint.repairAction || joint.repairDate || joint.repairWelderStamp || joint.repairVikResult && joint.repairVikResult !== "Не проводился" || joint.repairNdtResult && joint.repairNdtResult !== "Не проводился" || joint.repairDupNdtResult && joint.repairDupNdtResult !== "Не проводился" || joint.vikResult === "Ремонт" || joint.ndtResult === "Ремонт" || joint.dupNdtResult === "Ремонт");
}
function formatGost32569JournalRow(joint, rowIndex, materials = [], lrvCatalog = []) {
	const col1 = String(rowIndex + 1);
	const gostType = joint.gostJointType?.trim() || "С17";
	const repairSuffix = isJointRepaired(joint) ? "Р" : "";
	const col2 = `${joint.jointNumber}${repairSuffix}, ${gostType}`;
	const namesList = (joint.welderFullName || "").split(",").map((s) => s.trim()).filter(Boolean);
	const stampsList = joint.welderStampsList && joint.welderStampsList.length > 0 ? joint.welderStampsList : (joint.welderStamp || "").replace(/^[^(]+\(([^)]+)\)$/, "$1").split(",").map((s) => s.trim()).filter(Boolean);
	let col3;
	if (namesList.length > 1 && namesList.length === stampsList.length) col3 = namesList.map((name, idx) => `${name}, ${stampsList[idx]}`).join("\n");
	else if (namesList.length > 0 && stampsList.length > 0) col3 = `${namesList.join(", ")}, ${joint.welderStamp || stampsList.join(", ")}`;
	else col3 = "н/п";
	const cert1 = (joint.elem1CertNumber ? [
		`серт. № ${joint.elem1CertNumber}`,
		joint.elem1HeatNumber ? `пл. ${joint.elem1HeatNumber}` : "",
		joint.elem1BatchNumber ? `парт. ${joint.elem1BatchNumber}` : ""
	].filter(Boolean) : [String(joint.elem1FactoryNumber ?? "").trim()].filter(Boolean)).join(", ").replace(/[()]/g, "").trim();
	const cert2 = (joint.elem2CertNumber ? [
		`серт. № ${joint.elem2CertNumber}`,
		joint.elem2HeatNumber ? `пл. ${joint.elem2HeatNumber}` : "",
		joint.elem2BatchNumber ? `парт. ${joint.elem2BatchNumber}` : ""
	].filter(Boolean) : [String(joint.elem2FactoryNumber ?? "").trim()].filter(Boolean)).join(", ").replace(/[()]/g, "").trim();
	const shortName1 = formatJournalElementName(joint.elem1Name, joint.lrv1Code, joint.rdCode, lrvCatalog);
	const shortName2 = formatJournalElementName(joint.elem2Name, joint.lrv2Code, joint.rdCode, lrvCatalog);
	const cleanElem1Title = `${joint.elem1Material || ""} ${shortName1}`.replace(/[()]/g, "").trim();
	const cleanElem2Title = `${joint.elem2Material || ""} ${shortName2}`.replace(/[()]/g, "").trim();
	const cleanNtd1 = (joint.elem1Ntd || "").replace(/[()]/g, "").trim();
	const cleanNtd2 = (joint.elem2Ntd || "").replace(/[()]/g, "").trim();
	const col4 = `${[
		cleanElem1Title,
		cleanNtd1,
		cert1
	].filter(Boolean).join(", ")}\n${[
		cleanElem2Title,
		cleanNtd2,
		cert2
	].filter(Boolean).join(", ")}`;
	const col5 = `${joint.diameterMm}х${joint.wallThickness}`;
	const formattedWeldDate = formatDateDDMMYY(joint.weldingDate) || "н/п";
	let formattedTemp = "";
	if (joint.ambientTemp && String(joint.ambientTemp).trim() !== "") {
		const rawT = String(joint.ambientTemp).trim();
		const numT = Number(rawT);
		formattedTemp = `${!rawT.startsWith("+") && !rawT.startsWith("-") && !Number.isNaN(numT) && numT > 0 ? `+${rawT}` : rawT} °С`;
	}
	const col6 = formattedTemp ? `${formattedWeldDate}, ${formattedTemp}` : formattedWeldDate;
	const col7 = joint.weldingType || "н/п";
	const col8 = formatGost32569ConsumablesCell(joint.weldingMaterials, materials);
	let col9 = "н/п";
	const rawPreheat = (joint.preheatTemp || "").trim();
	if (rawPreheat && Number(rawPreheat) > 0) col9 = `${rawPreheat.startsWith("+") ? rawPreheat : `+${rawPreheat}`} °С`;
	else if (joint.ambientTemp && !Number.isNaN(Number(joint.ambientTemp)) && Number(joint.ambientTemp) <= 0) col9 = "+120…+150 °С";
	const col10 = normalizeGostNotApplicable(joint.rootWeldControl) || "н/п";
	Boolean(joint.elem1Material?.includes("Х") || joint.elem2Material?.includes("Х"));
	const col11 = normalizeGostNotApplicable(joint.steeloscopyInfo) || "н/п";
	const col12 = normalizeGostNotApplicable(joint.heatTreatOperator) || "н/п";
	const col13 = normalizeGostNotApplicable(joint.heatTreatDiagramNumber) || "н/п";
	const col14 = normalizeGostNotApplicable(joint.hardnessTestInfo) || "н/п";
	const col15 = joint.vikResult && joint.vikResult !== "Не проводился" ? `${joint.vikResult}${joint.vikReportNumber?.trim() ? `, № ${joint.vikReportNumber.trim()}` : ""}${joint.vikDate ? `, ${formatDateDDMMYY(joint.vikDate)}` : ""}` : "н/п";
	let col16;
	if (joint.ndtType && joint.ndtType !== "Не требуется" && joint.ndtResult && joint.ndtResult !== "Не проводился") {
		const repNo = joint.ndtReportNumber?.trim();
		const repPart = repNo ? `, № ${repNo}` : "";
		const datePart = joint.ndtDate ? `, ${formatDateDDMMYY(joint.ndtDate)}` : "";
		col16 = `${joint.ndtType}, ${joint.ndtResult}${repPart}${datePart}`;
	} else col16 = "н/п";
	joint.elem1Material.includes("12Х18Н10Т") || joint.elem2Material.includes("12Х18Н10Т");
	const col17 = normalizeGostNotApplicable(joint.ferritePhaseInfo) || "н/п";
	return {
		col1,
		col2,
		col3,
		col4,
		col5,
		col6,
		col7,
		col8,
		col9,
		col10,
		col11,
		col12,
		col13,
		col14,
		col15,
		col16,
		col17,
		cells: [
			col1,
			col2,
			col3,
			col4,
			col5,
			col6,
			col7,
			col8,
			col9,
			col10,
			col11,
			col12,
			col13,
			col14,
			col15,
			col16,
			col17
		]
	};
}
