async function fetchAllPaginated(path, mapper, pageSize = 500) {
	const results = [];
	let offset = 0;
	while (true) {
		const page = await apiRequest(`${path}${path.includes("?") ? "&" : "?"}limit=${pageSize}&offset=${offset}`);
		const items = Array.isArray(page.items) ? page.items : [];
		for (const raw of items) results.push(mapper(raw));
		offset += items.length;
		if (items.length === 0 || offset >= page.total) break;
	}
	return results;
}
