function parseCsvTextToRows(text) {
	const lines = text.replace(/^\uFEFF/, "").split(/\r?\n/).filter((l) => l.trim().length > 0);
	if (lines.length < 2) return [];
	const delimiter = lines[0].includes(";") ? ";" : ",";
	const splitLine = (line) => {
		const out = [];
		let cur = "";
		let inQuotes = false;
		for (let i = 0; i < line.length; i++) {
			const ch = line[i];
			if (ch === "\"") {
				if (inQuotes && line[i + 1] === "\"") {
					cur += "\"";
					i++;
				} else inQuotes = !inQuotes;
			} else if (ch === delimiter && !inQuotes) {
				out.push(cur.trim());
				cur = "";
			} else cur += ch;
		}
		out.push(cur.trim());
		return out;
	};
	const headers = splitLine(lines[0]);
	return lines.slice(1).map((line) => {
		const vals = splitLine(line);
		const rec = {};
		headers.forEach((h, idx) => {
			if (h) rec[h] = vals[idx] ?? "";
		});
		return rec;
	});
}
async function parseSpreadsheetFile(file) {
	if (file.name.toLowerCase().endsWith(".csv")) try {
		return await zaychickApi.parseSpreadsheet(file);
	} catch {
		return parseCsvTextToRows(await file.text());
	}
	return zaychickApi.parseSpreadsheet(file);
}
